using System;
using System.IO;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using System.Diagnostics;
using System.Threading.Tasks;
using System.Windows.Forms;
class MediaPreview:Panel {
 readonly PictureBox image=new PictureBox();readonly Label placeholder,clock,hint;readonly GlowButton play=new GlowButton(),open=new GlowButton();readonly Slider seek=new Slider();string root,path;double duration,seconds;int serial;bool playing,updating;Process worker;MemoryStream imageStream;
 public double PositionSeconds{get{return seconds;}}public double DurationSeconds{get{return duration;}}public Image DisplayImage{get{return image.Image;}}public string SourcePath{get{return path;}}
 public MediaPreview(string engineFolder){root=engineFolder;BackColor=Color.FromArgb(19,21,27);DoubleBuffered=true;image.SizeMode=PictureBoxSizeMode.Zoom;image.BackColor=BackColor;Controls.Add(image);placeholder=Skin.Label("Выберите файл для предпросмотра",0,0,400,70,12,false);placeholder.ForeColor=Skin.Muted;placeholder.TextAlign=ContentAlignment.MiddleCenter;placeholder.BackColor=BackColor;Controls.Add(placeholder);clock=Skin.Label("00:00 / 00:00",0,0,180,26,9,false);clock.ForeColor=Skin.Muted;Controls.Add(clock);hint=Skin.Label("Предпросмотр без звука",0,0,500,24,8,false);hint.ForeColor=Skin.Muted;Controls.Add(hint);play.Text="▶";Controls.Add(play);play.Click+=async(s,e)=>{if(playing)Stop();else await Play();};open.Text="Открыть оригинал";Controls.Add(open);open.Click+=(s,e)=>{if(!string.IsNullOrEmpty(path))try{Process.Start(path);}catch(Exception ex){MessageBox.Show(ex.Message);}};seek.Maximum=1000;Controls.Add(seek);seek.ValueChanged+=(s,e)=>{if(!updating){seconds=duration*seek.Value/1000d;UpdateClock();}};seek.MouseUp+=async(s,e)=>await Seek();seek.KeyUp+=async(s,e)=>await Seek();}
 static bool Video(string value){return Array.IndexOf(new[]{".mp4",".mkv",".mov",".avi",".webm",".m4v",".wmv",".flv"},Path.GetExtension(value??"").ToLowerInvariant())>=0;}
 static bool Picture(string value){return Array.IndexOf(new[]{".png",".jpg",".jpeg",".webp",".gif",".bmp",".tif",".tiff"},Path.GetExtension(value??"").ToLowerInvariant())>=0;}
 public void Stop(){serial++;playing=false;play.Text="▶";try{if(worker!=null&&!worker.HasExited)worker.Kill();}catch{}worker=null;}
 void SetImage(Image next){var previous=image.Image;image.Image=next;if(previous!=null)previous.Dispose();placeholder.Visible=next==null;}
 public async Task LoadSource(string file){if(file==path)return;Stop();int version=serial;path=file;seconds=0;duration=0;UpdateClock();SetImage(null);if(imageStream!=null){imageStream.Dispose();imageStream=null;}placeholder.Text=string.IsNullOrEmpty(file)?"Выберите файл для предпросмотра":Path.GetFileName(file);play.Enabled=seek.Enabled=false;open.Enabled=!string.IsNullOrEmpty(file);hint.Text=Video(file)?"Кадры предпросмотра — без звука":"Локальный предпросмотр";if(string.IsNullOrEmpty(file)||!File.Exists(file))return;
  if(Picture(file)&&Path.GetExtension(file).ToLowerInvariant()!=".webp"){try{imageStream=new MemoryStream(File.ReadAllBytes(file));SetImage(Image.FromStream(imageStream));hint.Text=image.Image.Width+" × "+image.Image.Height+" · изображение";return;}catch{if(imageStream!=null){imageStream.Dispose();imageStream=null;}}}
  try{double length=await Task.Run(()=>MediaJob.Duration(file,root));if(IsDisposed||version!=serial)return;duration=length;play.Enabled=seek.Enabled=Video(file)&&length>0;UpdateClock();if(Video(file)||Picture(file))await Frame(version);else{placeholder.Text=Path.GetFileName(file)+"\n\n"+(length>0?"Аудио · "+Time(length):"Документ");hint.Text="Файл готов к обработке";}}catch{if(!IsDisposed&&version==serial)placeholder.Text="Предпросмотр недоступен\n"+Path.GetFileName(file);}
 }
 async Task Seek(){if(string.IsNullOrEmpty(path)||!Video(path))return;Stop();await Frame(serial);}
 async Task Frame(int version){string file=path;double position=Math.Min(seconds,Math.Max(0,duration-.05));try{byte[] bytes=await Task.Run(()=>{using(var p=new Process()){if(version!=serial)return null;p.StartInfo=new ProcessStartInfo(Path.Combine(root,"ffmpeg.exe"),"-v error -ss "+GifOptions.N(position)+" -i \""+file+"\" -frames:v 1 -vf scale=960:-1 -f image2pipe -vcodec mjpeg -"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};worker=p;p.Start();var error=p.StandardError.ReadToEndAsync();using(var ms=new MemoryStream()){p.StandardOutput.BaseStream.CopyTo(ms);p.WaitForExit();if(p.ExitCode!=0)throw new Exception(error.Result);return ms.ToArray();}}});if(IsDisposed||version!=serial||bytes==null)return;using(var stream=new MemoryStream(bytes))using(var source=Image.FromStream(stream))SetImage(new Bitmap(source));}catch{if(!IsDisposed&&version==serial)placeholder.Text="Нет кадра для предпросмотра";}}
 async Task Play(){if(string.IsNullOrEmpty(path)||!Video(path))return;if(seconds>=duration-.1)seconds=0;Stop();int version=serial;double start=seconds;string file=path;playing=true;play.Text="Ⅱ";try{await Task.Run(()=>{using(var p=new Process()){if(version!=serial)return;p.StartInfo=new ProcessStartInfo(Path.Combine(root,"ffmpeg.exe"),"-v error -re -ss "+GifOptions.N(start)+" -i \""+file+"\" -an -vf \"fps=12,scale=640:360:force_original_aspect_ratio=decrease,pad=640:360:(ow-iw)/2:(oh-ih)/2\" -pix_fmt bgr24 -f rawvideo -"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};worker=p;p.Start();var error=p.StandardError.ReadToEndAsync();byte[] buffer=new byte[640*360*3];int number=0;while(version==serial){int received=0;while(received<buffer.Length){int n=p.StandardOutput.BaseStream.Read(buffer,received,buffer.Length-received);if(n==0)break;received+=n;}if(received!=buffer.Length)break;var frame=new Bitmap(640,360,PixelFormat.Format24bppRgb);var data=frame.LockBits(new Rectangle(0,0,640,360),ImageLockMode.WriteOnly,PixelFormat.Format24bppRgb);Marshal.Copy(buffer,0,data.Scan0,buffer.Length);frame.UnlockBits(data);double time=start+(++number)/12d;try{BeginInvoke(new Action(()=>{if(IsDisposed||version!=serial){frame.Dispose();return;}SetImage(frame);seconds=Math.Min(duration,time);updating=true;seek.Value=duration>0?(int)(1000*seconds/duration):0;updating=false;UpdateClock();}));}catch{frame.Dispose();break;}}if(version!=serial)try{p.Kill();}catch{}p.WaitForExit();}});}catch{}finally{if(!IsDisposed&&version==serial){playing=false;play.Text="▶";}}}
 static string Time(double n){return TimeSpan.FromSeconds(Math.Max(0,n)).ToString(n>=3600?@"hh\:mm\:ss":@"mm\:ss");}
 void UpdateClock(){clock.Text=Time(seconds)+" / "+Time(duration)+(Video(path)?" · без звука":"");}
 protected override void OnResize(EventArgs e){base.OnResize(e);if(placeholder==null)return;image.SetBounds(10,10,Math.Max(1,Width-20),Math.Max(1,Height-100));placeholder.SetBounds(20,20,Math.Max(1,Width-40),Math.Max(50,Height-125));play.SetBounds(12,Height-78,44,32);clock.SetBounds(69,Height-72,245,24);open.SetBounds(Math.Max(260,Width-192),Height-78,180,32);seek.SetBounds(12,Height-40,Math.Max(1,Width-24),20);hint.Visible=false;}
 protected override void Dispose(bool disposing){if(disposing){Stop();if(image.Image!=null){image.Image.Dispose();image.Image=null;}if(imageStream!=null)imageStream.Dispose();}base.Dispose(disposing);}
}
